using System;using System.IO;using System.Reflection;using System.Threading;using System.Web.Script.Serialization;using System.Collections.Generic;
class DashboardAcceptance {
 static int Main(){string scratch=Path.Combine(Environment.CurrentDirectory,"artifacts","scan-lease-test-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(scratch);string dir=Path.Combine(scratch,"parent");Directory.CreateDirectory(dir);string file=Path.Combine(dir,"safe.txt");File.WriteAllText(file,"harmless lease fixture");try{using(var lease=NativeScanLease.Open(file)){bool refused=false;try{Directory.Move(dir,dir+"-moved");}catch(IOException){refused=true;}if(!refused)throw new Exception("Ancestor rename permitted");refused=false;try{File.WriteAllText(file,"modified");}catch(IOException){refused=true;}if(!refused)throw new Exception("Retained file modified");}Console.WriteLine("Retained ancestor/file replacement checks PASS");}finally{Directory.Delete(scratch,true);}
 var json=new JavaScriptSerializer();Console.WriteLine("Actual device snapshot: "+json.Serialize(DeviceHealth.Snapshot().GetAwaiter().GetResult()));using(var protection=new NativeSecurity(t=>Console.WriteLine("Notification observed"))){string folder=(string)typeof(NativeSecurity).GetMethod("Downloads",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,null);string test=Path.Combine(folder,"Sentinel-scan-check-"+Guid.NewGuid().ToString("N"));try{
  Dictionary<string,object> value=null;for(int i=0;i<40;i++){Thread.Sleep(1000);value=json.Deserialize<Dictionary<string,object>>(json.Serialize(protection.Snapshot()));if(Convert.ToBoolean(value["available"]))break;}if(!Convert.ToBoolean(value["available"]))throw new Exception(Convert.ToString(value["error"]));protection.SetMonitoring(true);Directory.CreateDirectory(test);File.WriteAllText(Path.Combine(test,"harmless.txt"),"Sentinel actual Downloads scan acceptance. Harmless text only.");
  for(int i=0;i<60;i++){Thread.Sleep(1000);value=json.Deserialize<Dictionary<string,object>>(json.Serialize(protection.Snapshot()));var text=json.Serialize(value);if(text.Contains("Download checked")){Console.WriteLine(text);if(text.Contains("scan unavailable or interrupted")||text.Contains("\"state\":\"failed\""))throw new Exception("Scan failed");Console.WriteLine("Actual Downloads arrival -> retained file -> Sentinel Rust engine -> activity PASS");return 0;}}throw new Exception("Download scan timed out");
 }finally{if(Directory.Exists(test))Directory.Delete(test,true);}}
 }
}
